query:
// Excludes Rahul himself and anyone who is already his direct friend.
MATCH path = (r:User {name:'Rahul'})-[:FRIEND*2]-(fof:User)
WHERE fof <> r
  AND NOT EXISTS { (r)-[:FRIEND]-(fof) }
RETURN path;

MATCH path = (r:User {name:'Rahul'})-[:FRIEND*1..3]-(other:User)
WHERE other <> r
RETURN path;

// Change the two names to test any pair (example: Rahul -> Meera).
MATCH (a:User {name:'Rahul'}), (b:User {name:'Meera'})
MATCH path = shortestPath((a)-[:FRIEND*]-(b))
RETURN path;

// Interpreted as the longest of all shortest paths (graph diameter):
// the pair of users who are furthest apart in the friendship network.
// Expected: 4 hops (Karan/Amit to Meera/Arjun); LIMIT 1 shows one such pair.
MATCH (a:User), (b:User)
WHERE elementId(a) < elementId(b)
MATCH path = shortestPath((a)-[:FRIEND*]-(b))
WITH path ORDER BY length(path) DESC LIMIT 1
RETURN path;

// Comments that have at least one reply, with the author and every replier.
MATCH (c:Comment)<-[:REPLIED_TO]-(:User)
WITH DISTINCT c
MATCH (u:User)-[rel:COMMENTED|REPLIED_TO]->(c)
RETURN u, rel, c;

// Topics discussed (commented or replied) by 2+ different users.
MATCH (u:User)-[:COMMENTED|REPLIED_TO]->(:Comment)-[:ABOUT]->(t:Topic)
WITH t, count(DISTINCT u) AS userCount
WHERE userCount >= 2
MATCH (u2:User)-[r:COMMENTED|REPLIED_TO]->(c:Comment)-[ab:ABOUT]->(t)
RETURN u2, r, c, ab, t;

// Threshold 0.10 chosen because the highest toxicity in the data is 0.12 (C005).
MATCH (u:User)-[r:COMMENTED|REPLIED_TO]->(c:Comment)
WHERE c.toxicity > 0.10
RETURN u, r, c;

// People Rahul is not yet friends with, reached through a mutual friend.
MATCH (r:User {name:'Rahul'})-[f1:FRIEND]-(mutual:User)-[f2:FRIEND]-(rec:User)
WHERE rec <> r
  AND NOT EXISTS { (r)-[:FRIEND]-(rec) }
RETURN r, f1, mutual, f2, rec;

MATCH (r:User {name:'Rahul'})-[:FRIEND]-(mutual:User)-[:FRIEND]-(rec:User)
WHERE rec <> r
  AND NOT EXISTS { (r)-[:FRIEND]-(rec) }
RETURN rec.name AS recommendation, count(mutual) AS mutualFriends, collect(mutual.name) AS via
ORDER BY mutualFriends DESC;

MATCH (n)
OPTIONAL MATCH (n)-[r]->(m)
RETURN n, r, m;
